/* C-3 authoring source for the three papers. Compact form: o[0] is the KEY, o[1..3] the distractors;
   e[] lines up with o[] (e[0] null = use `why`). tools/c3-build.js places the key at the planned position
   and writes data/tests.js. Domains: lit | hist | hum | sci. */
module.exports = {
placement: [
{ id:"pl-01", t:"wic", d:"sci", lv:"B2", f:"claim", w:"corroborate",
  p:"A team of ecologists reported that a rare frog had returned to a hillside stream, but their only evidence was one night of recorded calls. The following spring, a second team, which had not seen the first study, photographed adult frogs and tadpoles at the same stream. These photographs ______ the original report.",
  o:["corroborated","contradicted","anticipated","summarised"],
  e:[null,"*Contradicted* runs the wrong way: photographs of frogs at the same stream support a report of frogs there.","*Anticipated* means came before; the photographs were taken the spring after the report.","*Summarised* means gave the main points of; the photographs add new evidence instead of restating the report."],
  why:"A second, independent team found the frogs at the same stream, so its photographs gave new, separate support to the report: they corroborated it.",
  h:"Did the second team work alone, and does its evidence agree or disagree with the first?" },
{ id:"pl-02", t:"wic", d:"hist", lv:"B2", f:"fix", w:"exacerbate",
  p:"In one riverside town in the 1850s, a dry summer had already left the wells low. The town council then allowed a new dye works to draw water from the river upstream, a decision that ______ the shortage: by August, families were queuing for hours at the last working pump.",
  o:["exacerbated","mitigated","concealed","predicted"],
  e:[null,"*Mitigated* means made less severe; the queues by August show the shortage grew worse.","*Concealed* means hid; the shortage was plain to see in the queues at the pump.","*Predicted* means said in advance; the council's decision acted on the shortage, it did not forecast it."],
  why:"The shortage already existed, and letting the dye works take river water made it worse, as the long queues show: making a bad situation worse is exacerbating it.",
  h:"Was the shortage better or worse after the council's decision? Look at what happened by August." },
{ id:"pl-03", t:"wic", d:"hum", lv:"B2", f:"visible", w:"opaque",
  p:"The museum's new guide to its collection won praise for its photographs, but many visitors found its text ______: the entries were long and full of technical terms that were never explained, and several readers said they gave up after only a few pages.",
  o:["opaque","candid","concise","vivid"],
  e:[null,"*Candid* means honest and open; nothing in the passage concerns whether the text told the truth.","*Concise* means brief and to the point; long entries full of unexplained terms are neither.","*Vivid* means bright and lively; the complaint is that the text was hard to understand."],
  why:"Unexplained technical terms made the text hard to understand, and readers gave up: writing that is hard to understand because nothing is made clear is opaque.",
  h:"What did the unexplained terms do to readers' understanding?" },
{ id:"pl-04", t:"wic", d:"sci", lv:"B2", f:"centre", w:"integral",
  p:"In many reef-building corals, tiny algae live inside the coral's tissues and supply it with most of the sugars it needs. When the water becomes too warm and the algae leave, the coral loses its colour and begins to starve. The algae are therefore ______ the coral's survival.",
  o:["integral to","peripheral to","incongruous with","immaterial to"],
  e:[null,"*Peripheral to* means at the edge of, of minor importance; without the algae the coral starves.","*Incongruous with* means out of place beside; the algae belong inside the coral and feed it.","*Immaterial to* means making no difference to; losing the algae makes the greatest difference of all."],
  why:"Without the algae the coral starves, so the algae are an essential part of its survival: integral to it.",
  h:"What happens to the coral when the algae leave?" },
{ id:"pl-05", t:"wic", d:"hum", lv:"B2", f:"fit", w:"disparate",
  p:"The festival's programme brought together performers from ______ traditions: a string quartet, a shadow-puppet troupe, a choir of market traders and a solo dancer trained in classical ballet. The organisers admitted that the only thread linking the acts was the town that hosted them.",
  o:["disparate","homogeneous","anomalous","prestigious"],
  e:[null,"*Homogeneous* means all of the same kind; the list shows four very different kinds of performance.","*Anomalous* means not fitting a pattern; there is no pattern here for any one tradition to break.","*Prestigious* means admired and respected; the passage is about how different the acts were, not their reputation."],
  why:"Quartet, puppets, choir and ballet have nothing in common except the host town, so the traditions were very different in kind: disparate.",
  h:"What do the four acts have in common, according to the organisers?" },
{ id:"pl-06", t:"wic", d:"hist", lv:"B2", f:"attitude", w:"ambivalent",
  p:"Letters written by students at a girls' boarding school in the early 1900s suggest that many felt ______ about a new rule requiring them to study science: they welcomed the chance to work in a laboratory, yet they complained that the extra lessons left no time for music and painting.",
  o:["ambivalent","indifferent","enthusiastic","ambiguous"],
  e:[null,"*Indifferent* means having no feeling either way; the students both welcomed and complained, so they cared.","*Enthusiastic* fits only the first half; the complaints about lost music and painting show the feeling was mixed.","*Ambiguous* describes words or evidence with two possible meanings, not a person's mixed feelings about a rule."],
  why:"The students welcomed the laboratory work yet complained about the lost time: two opposite feelings about one thing at once is being ambivalent.",
  h:"Find one positive reaction and one negative reaction in the letters." },
{ id:"pl-07", t:"wic", d:"sci", lv:"B2", f:"depend", w:"contingent-on",
  p:"In a laboratory study, females of one desert beetle species laid eggs only after the air reached a certain level of humidity; in dry air they waited, sometimes for weeks. Egg-laying in this species therefore appears to be ______ moisture in the air.",
  o:["contingent on","independent of","harmful to","a substitute for"],
  e:[null,"*Independent of* means not affected by; the beetles waited in dry air, so moisture clearly affects egg-laying.","*Harmful to* would mean egg-laying damages moisture, which makes no sense; the study links egg-laying to humid air.","*A substitute for* means used in place of; egg-laying does not replace moisture, it waits for it."],
  why:"The beetles laid eggs only once the air was humid enough, so egg-laying happens only on that condition: it is contingent on moisture.",
  h:"When did the beetles lay eggs, and when did they wait?" },
{ id:"pl-08", t:"wic", d:"hum", lv:"C1", f:"claim", w:"tenuous",
  p:"A critic has argued that a painter's late landscapes were inspired by a visit to the coast, yet the only evidence offered is that two of the canvases contain a great deal of blue. Since the painter favoured blue throughout her career, most scholars regard the critic's argument as ______.",
  o:["tenuous","conclusive","persuasive","influential"],
  e:[null,"*Conclusive* means settling the question; a colour she favoured throughout her career settles nothing.","*Persuasive* means convincing; the scholars point out a weakness in the evidence instead of praising it.","*Influential* means having an effect on others; the passage is about how well the argument is supported, not its effect."],
  why:"The painter favoured blue throughout her career, so its presence proves nothing about the coast: the argument is supported only very weakly.",
  h:"Does the blue in two canvases really point to the coast, given the rest of her work?" },
{ id:"pl-09", t:"wic", d:"sci", lv:"C1", f:"fix", w:"stymie",
  p:"A team of engineers set out to build a robot that could map flooded caves. Silt has ______ the project from the start: every movement of the robot stirs up fine mud that blinds its cameras, so most underwater trials have ended within minutes.",
  o:["stymied","accelerated","sanctioned","mitigated"],
  e:[null,"*Accelerated* means sped up; trials that end within minutes show the project being held back.","*Sanctioned* means approved or penalised by an authority; silt is not an authority, and it blocks the work.","*Mitigated* means made a harm less severe; the project is not a harm, and silt makes the work harder."],
  why:"The silt blinds the cameras and ends the trials early, so it has blocked the project's progress: it has stymied the project.",
  h:"What does the silt do to the robot's trials?" },
{ id:"pl-10", t:"wic", d:"lit", lv:"C2", f:"visible", w:"belie",
  p:"The cottage's cheerful yellow shutters and neat window boxes ______ the state of its interior. Inside, Nam found damp walls, a collapsed staircase and a kitchen that clearly had not been used for years.",
  o:["belied","revealed","attested to","mirrored"],
  e:[null,"*Revealed* means showed; the bright outside gave no sign of the damp, broken rooms.","*Attested to* means gave evidence of; the shutters suggested a cared-for home, not a ruined one.","*Mirrored* means matched; the cheerful outside was the opposite of the neglected inside."],
  why:"The cheerful outside gave a false idea of the neglected inside: when an appearance gives a false impression of something, it belies it.",
  h:"Did the outside of the cottage match what Nam found inside?" },
{ id:"pl-11", t:"wic", d:"hist", lv:"C1", f:"centre", w:"dearth",
  p:"Historians of the region's early textile trade face ______ written sources. The merchants kept few records, and most of those they did keep were lost when the warehouses that stored them burned, so much of what is known today comes from the surviving cloth itself.",
  o:["a dearth of","a wealth of","a demand for","a dispute over"],
  e:[null,"*A wealth of* means a great deal of; few records, most of them lost, leave very little to work with.","*A demand for* means people asking for something; the passage is about how few sources survive.","*A dispute over* means an argument about; nothing suggests historians disagree about the sources."],
  why:"Few records were kept and most were lost, so historians have too few written sources: a dearth of them.",
  h:"How many written sources survive, according to the passage?" },
{ id:"pl-12", t:"wic", d:"sci", lv:"C1", f:"fit", w:"incongruous-with",
  p:"Botanists surveying a high mountain meadow recorded a single seedling of a tropical palm growing among the grasses and mosses. The plant seemed so ______ its cold, windswept surroundings that the team first assumed a visitor had dropped it there by accident.",
  o:["incongruous with","integral to","contingent on","consistent with"],
  e:[null,"*Integral to* means an essential part of; a lone tropical seedling is no part of a cold meadow.","*Contingent on* means depending on; the point is that the palm did not fit its setting, not that it relied on it.","*Consistent with* means in keeping with; the team's first guess shows the palm looked out of place."],
  why:"A tropical palm among mountain grasses looked so out of place that the botanists suspected an accident: it was incongruous with its surroundings.",
  h:"Why did the team think a visitor had dropped the plant?" },
{ id:"pl-13", t:"wic", d:"lit", lv:"C1", f:"attitude", w:"sanguine",
  p:"The family's noodle shop had just had its worst month in years, and Praew's parents spoke of little else. Grandmother Bua alone remained ______. 'Rain empties the streets every August,' she said, stirring the broth, 'and every September they fill again.'",
  o:["sanguine","despondent","recalcitrant","indifferent"],
  e:[null,"*Despondent* means without hope; Bua expects the customers to return as they always have.","*Recalcitrant* means stubbornly refusing to obey or cooperate; Bua is not resisting anyone.","*Indifferent* means not caring; she speaks about the shop's future, so she cares, she simply is not worried."],
  why:"While the others worry, Bua calmly expects business to recover in September: quiet confidence about a good outcome in a hard time is being sanguine.",
  h:"What does Bua expect to happen in September?" },
{ id:"pl-14", t:"wic", d:"hist", lv:"C1", f:"depend", w:"prevail-over",
  p:"For three years, members of a weavers' cooperative argued over whether to keep their hand looms or replace them with machines. In the end, those who favoured the hand looms ______ their rivals, and the cooperative's workshop still produces all of its cloth by hand.",
  o:["prevailed over","succumbed to","collaborated with","depended on"],
  e:[null,"*Succumbed to* means gave way to; the workshop still weaves by hand, so the hand-loom side won.","*Collaborated with* means worked together with; the two sides argued for three years until one view won.","*Depended on* means relied on; the passage describes a contest that one side won, not reliance."],
  why:"The workshop still uses hand looms, so their supporters won the long argument: they prevailed over their rivals.",
  h:"Which side's view does the workshop follow today?" },
{ id:"pl-15", t:"transition", d:"sci", lv:"B2", f:"transition", w:null,
  p:"In a garden experiment, bees learned to collect sugar water from blue feeders. The researchers then removed the blue feeders and set out empty yellow ones elsewhere, yet the bees kept returning to the bare spots where the blue feeders had stood. ______ the researchers concluded that the bees remembered where the food had been, not just its colour.",
  o:["Therefore,","However,","For example,","Similarly,"],
  e:[null,"*However* signals a contrast; the conclusion agrees with what the bees did instead of pulling against it.","*For example* introduces an instance of a general point; the conclusion is drawn from the observation, not an instance of it.","*Similarly* adds a parallel case; the last sentence is a conclusion, not a second, matching case."],
  why:"The bees' return to the empty spots is the evidence, and the conclusion follows from it, so a result word is needed.",
  h:"Does the last sentence pull against the observation, add to it, or follow from it?" },
{ id:"pl-16", t:"transition", d:"hum", lv:"C1", f:"transition", w:"that-said",
  p:"The new translation of the poem is far more faithful to the original than any earlier version, keeping even the poet's unusual line breaks. ______ the translator's introduction is disappointingly brief, offering only two pages on a poet whose life most readers know little about.",
  o:["That said,","Therefore,","Specifically,","Moreover,"],
  e:[null,"*Therefore* signals a result; a faithful translation does not cause a short introduction.","*Specifically* gives a more exact version of the previous point; the brief introduction is a new, critical point.","*Moreover* adds a point in the same direction; here praise is followed by criticism, so the direction changes."],
  why:"The praise of the translation still stands, and the second sentence adds a limit to it: that is a concession, signalled by that said.",
  h:"Does the second sentence cancel the praise, follow from it, or limit it?" }
],

stage: [
{ id:"sv-01", t:"wic", d:"lit", lv:"B2", f:"fix", w:"mitigate",
  p:"Fern knew that her speech to the school assembly would be long, so she printed it in large type and marked every place to pause. These small preparations could not remove her nerves entirely, but they did a good deal to ______ them.",
  o:["mitigate","exacerbate","corroborate","precipitate"],
  e:[null,"*Exacerbate* means make worse; the preparations were meant to help, and 'could not remove' shows they helped partly.","*Corroborate* means support a claim with independent evidence; nerves are a feeling, not a claim.","*Precipitate* means make something happen suddenly; the nerves were already there."],
  why:"The preparations could not end her nerves but made them less severe; making a harm less severe without removing it is what mitigate means.",
  h:"Did the preparations make her nerves weaker or stronger?" },
{ id:"sv-02", t:"wic", d:"sci", lv:"B2", f:"fit", w:"homogeneous",
  p:"To test a new fertiliser fairly, the agronomists planted a field with seeds from a single, carefully bred variety of wheat, so that every plant shared nearly the same genes. Because the crop was so ______, any difference in growth between plots could be traced to the fertiliser rather than to the plants themselves.",
  o:["homogeneous","disparate","dispersed","resilient"],
  e:[null,"*Disparate* means very different in kind; the plants shared nearly the same genes.","*Dispersed* means spread out over an area; the point is how alike the plants were, not where they grew.","*Resilient* means able to recover; how hardy the wheat was would not rule out genetic differences between plots."],
  why:"Nearly identical genes made the crop all of one kind, so differences in growth had to come from the fertiliser: the crop was homogeneous.",
  h:"What did the plants share, and why did that matter for a fair test?" },
{ id:"sv-03", t:"wic", d:"hist", lv:"B2", f:"centre", w:"peripheral",
  p:"Early accounts of the town's founding focused on the merchants who built its harbour and treated the farmers in the surrounding valley as ______ the story. A recent study of tax rolls challenges that view, showing that farm produce made up most of what passed through the harbour.",
  o:["peripheral to","integral to","opposed to","a proxy for"],
  e:[null,"*Integral to* means essential to; that is the recent study's view, which challenges the early accounts.","*Opposed to* means against; nothing suggests the accounts presented the farmers as hostile to anything.","*A proxy for* means a stand-in measure of; the accounts left the farmers at the edge, they did not use them to measure anything."],
  why:"The early accounts centred on the merchants and pushed the farmers to the edge of the story; the new study argues the farmers were central.",
  h:"Where did the early accounts put the farmers, and what does the new study challenge?" },
{ id:"sv-04", t:"wic", d:"hum", lv:"B2", f:"visible", w:"opaque",
  p:"Many readers find the philosopher's early essays ______: her sentences run to a page or more, she invents terms without defining them, and she rarely gives an example. Her later lectures, written for a general audience, are by contrast remarkably easy to follow.",
  o:["opaque","transparent","facile","tenuous"],
  e:[null,"*Transparent* means easy to understand; that describes the later lectures, which are set in contrast.","*Facile* means too simple or shallow; page-long sentences and undefined terms make the essays difficult, not simple.","*Tenuous* means weakly supported; the complaint is about how hard the essays are to understand, not how well argued."],
  why:"Page-long sentences, undefined terms and no examples make the essays hard to understand, unlike the easy later lectures: they are opaque.",
  h:"What makes the essays hard going, and how are the later lectures different?" },
{ id:"sv-05", t:"wic", d:"sci", lv:"B2", f:"fit", w:"anomaly",
  p:"Over ten years of monitoring, every nest box in the woodland study area was used by the same species of small songbird. In the eleventh spring, one box was occupied instead by a pair of bats, ______ that the researchers recorded but could not explain.",
  o:["an anomaly","a correlation","a hypothesis","a corroboration"],
  e:[null,"*A correlation* is a link between two things that vary together; one pair of bats in one box is a single break in a pattern, not a link.","*A hypothesis* is a proposed explanation; the researchers recorded the case but could not explain it.","*A corroboration* is new support for a claim; the bats break the ten-year pattern instead of supporting anything."],
  why:"Ten years of songbirds form a clear pattern, and the bats break it: something that does not fit an otherwise regular pattern is an anomaly.",
  h:"Was there a regular pattern, and did the bats fit it?" },
{ id:"sv-06", t:"wic", d:"lit", lv:"B2", f:"attitude", w:"ambivalent",
  p:"Kwan had longed for years to leave the village for the city, yet on the morning of her departure she lingered at the gate, running her hand along the old wooden posts. The narrator presents her as deeply ______ about the move, eager to go and unwilling to let go.",
  o:["ambivalent","sanguine","indifferent","resentful"],
  e:[null,"*Sanguine* means calmly confident that things will go well; the narrator stresses her divided feelings, not her expectations.","*Indifferent* means not caring; someone who longs to leave and lingers at the gate cares a great deal.","*Resentful* means bitter about unfair treatment; nothing suggests anyone has wronged her."],
  why:"Kwan is eager to go and unwilling to let go at the same time; holding two opposite feelings about one thing is being ambivalent.",
  h:"How many feelings does the narrator give Kwan, and do they point the same way?" },
{ id:"sv-07", t:"wic", d:"sci", lv:"C1", f:"centre", w:"dearth",
  p:"Ecologists have long suspected that a small nocturnal mammal nests in the forest canopy, high above the ground. The idea remains unconfirmed largely because of ______ reliable observations: very few researchers have the equipment or training to climb sixty metres into the treetops at night.",
  o:["a dearth of","an abundance of","a dispute about","a bias towards"],
  e:[null,"*An abundance of* means a great many; the colon explains that very few researchers can make such observations.","*A dispute about* means an argument over; the passage gives a shortage of observers as the reason, not a disagreement.","*A bias towards* means an unfair preference for; nothing suggests researchers favour one kind of observation."],
  why:"Few researchers can climb into the treetops at night, so there are too few reliable observations: a dearth of them.",
  h:"Read the part after the colon: how many people can make these observations?" },
{ id:"sv-08", t:"wic", d:"hum", lv:"C1", f:"centre", w:"integral",
  p:"In the choreographer's best-known work, the dancers' silences are not pauses between movements but ______ the piece: whenever the music stops, the stillness on stage carries as much meaning as any leap, and critics have argued that the work would collapse without it.",
  o:["integral to","tangential to","antithetical to","inconsequential to"],
  e:[null,"*Tangential to* means only touching the edge of; critics say the work would collapse without the stillness.","*Antithetical to* means directly opposed to; the stillness carries the work's meaning instead of working against it.","*Inconsequential to* means making no difference to; a work that would collapse without the stillness depends on it completely."],
  why:"The stillness carries meaning and the work would collapse without it, so the silences are an essential part of the piece: integral to it.",
  h:"What do critics say would happen to the work without the stillness?" },
{ id:"sv-09", t:"wic", d:"hist", lv:"C1", f:"claim", w:"substantiate",
  p:"A local legend held that the first schoolhouse in the valley was built by the girls who studied there, carrying the stones up from the river themselves. When historians examined the district's building records, however, they found nothing to ______ the story: the records name only a team of hired masons.",
  o:["substantiate","refute","embellish","disseminate"],
  e:[null,"*Refute* means prove wrong; records naming only hired masons count against the legend, so 'nothing to refute the story' runs the wrong way.","*Embellish* means add decorative details to; the historians were checking the legend against records, not adding to it.","*Disseminate* means spread widely; the question is whether the records support the legend, not whether they spread it."],
  why:"The records name only hired masons, so they give no evidence that the girls built the schoolhouse: nothing substantiates the legend.",
  h:"Do the building records support the legend or work against it?" },
{ id:"sv-10", t:"wic", d:"sci", lv:"C1", f:"visible", w:"latent",
  p:"Some plant viruses can remain ______ in a crop for several seasons, causing no visible damage to leaves or fruit. Only when the plants are stressed by drought or heat do the first yellow spots appear, by which time the infection may have spread through an entire field.",
  o:["latent","manifest","virulent","peripheral"],
  e:[null,"*Manifest* means plainly visible; the virus causes no visible damage until the plants are stressed.","*Virulent* means severe and harmful; for several seasons the virus causes no damage at all.","*Peripheral* means at the edge or of minor importance; the point is that the infection is present but hidden."],
  why:"The virus is present for seasons but shows no sign until drought or heat brings out the spots: present but hidden and not yet active is latent.",
  h:"Is the virus absent, hidden or visible during those seasons?" },
{ id:"sv-11", t:"wic", d:"lit", lv:"C1", f:"depend", w:"contingent-on",
  p:"Aunt Pim had promised to lend Mook the old bicycle, but the promise was ______ Mook's school report: if every mark was a pass, the bicycle was hers for the summer; if not, it would stay locked in the shed.",
  o:["contingent on","immaterial to","incongruous with","a substitute for"],
  e:[null,"*Immaterial to* means making no difference to; the report decides whether Mook gets the bicycle.","*Incongruous with* means out of place beside; the promise and the report are linked by a condition, not a mismatch.","*A substitute for* means used in place of; the bicycle is a reward that depends on the report, not a replacement for it."],
  why:"Mook gets the bicycle only if every mark is a pass, so the promise depends on the report: it is contingent on it.",
  h:"What has to happen before Mook gets the bicycle?" },
{ id:"sv-12", t:"wic", d:"hist", lv:"C1", f:"claim", w:"attest-to",
  p:"No written description of the old ferry crossing survives. Its importance to the river towns is nonetheless clear: the deep ruts worn into the stone landing on each bank, and the hundreds of lost coins found in the mud beside them, ______ centuries of heavy traffic.",
  o:["attest to","conceal","account for","prevail over"],
  e:[null,"*Conceal* means hide; the ruts and coins make the long traffic plain to see.","*Account for* means explain or cause; the traffic caused the ruts, not the other way round.","*Prevail over* means win against; ruts and coins are not competing with the traffic."],
  why:"The worn ruts and lost coins are evidence of long, heavy use: when things show that something is true, they attest to it.",
  h:"What do the ruts and the coins show about the crossing?" },
{ id:"sv-13", t:"wic", d:"hum", lv:"C1", f:"depend", w:"proxies-for",
  p:"Because no one recorded how many people read the town's newspapers in the nineteenth century, one historian uses the number of copies sold each week as ______ readership, while noting that a single copy was often shared among several households.",
  o:["a proxy for","a harbinger of","a barrier to","a dearth of"],
  e:[null,"*A harbinger of* is a sign that something is coming; the sales figures estimate readership at the time, they do not announce it.","*A barrier to* is something that blocks; copies sold do not stop people reading.","*A dearth of* means a lack of; the sales figures are used to estimate readership, not to show a shortage."],
  why:"Readership was never recorded, so the historian counts copies sold in its place: a measurable stand-in for something unmeasured is a proxy for it.",
  h:"Readership cannot be counted directly. What does the historian count instead, and why?" },
{ id:"sv-14", t:"wic", d:"sci", lv:"C1", f:"claim", w:"buttress",
  p:"The geologist's claim that the valley had been carved by a glacier rested at first on the shape of its walls alone. She later ______ the argument with two further lines of evidence: scratches on the exposed bedrock and boulders that could only have been carried from mountains far to the north.",
  o:["buttressed","undermined","stymied","conceded"],
  e:[null,"*Undermined* means weakened; scratches and carried boulders add support for a glacier.","*Stymied* means blocked the progress of; the new evidence moved her argument forward.","*Conceded* means admitted defeat on a point; she was adding evidence for her own claim, not giving it up."],
  why:"Two new kinds of evidence gave the glacier claim extra support and made it stronger: she buttressed it.",
  h:"Did the scratches and boulders strengthen or weaken her claim?" },
{ id:"sv-15", t:"wic", d:"hist", lv:"C1", f:"fix", w:"ameliorate",
  p:"After a flood destroyed many of the city's workshops, a group of women weavers set up a lending fund that gave members small loans to buy new looms. The fund could not restore the trade to its former size, but it noticeably ______ the hardship of many families in the years that followed.",
  o:["ameliorated","exacerbated","attested to","sanctioned"],
  e:[null,"*Exacerbated* means made worse; loans for new looms helped families, even if the trade never fully recovered.","*Attested to* means gave evidence of; the fund acted on the hardship, it did not prove the hardship existed.","*Sanctioned* means officially approved or punished; a lending fund does not approve hardship, it eases it."],
  why:"The loans did not fully restore the trade but made the families' hardship less bad; improving a bad situation without solving it is ameliorating it.",
  h:"Did the fund make things better or worse, and did it solve the problem completely?" },
{ id:"sv-16", t:"wic", d:"lit", lv:"C1", f:"visible", w:"manifest",
  p:"At the clinic, Ploy's patience was ______ even the smallest tasks: she explained each step slowly to frightened children and listened calmly to the same complaint for the third time in an hour.",
  o:["manifest in","concealed by","peripheral to","a proxy for"],
  e:[null,"*Concealed by* means hidden by; her slow explanations and calm listening put her patience on show.","*Peripheral to* means of minor importance to; the examples show patience in everything she does, even the smallest tasks.","*A proxy for* means a stand-in measure of; her patience shows in her tasks, it does not measure them."],
  why:"Slow explanations and calm listening display her patience plainly in each task: a quality that shows itself plainly in something is manifest in it.",
  h:"Do her actions hide her patience or show it?" },
{ id:"sv-17", t:"wic", d:"hum", lv:"C1", f:"claim", w:"tenuous",
  p:"A recent biography suggests that the composer wrote her famous lullaby for a niece, but the evidence is ______ at best: the niece is never mentioned in the composer's letters, and the only link is a dedication 'to a little one' added by a later publisher.",
  o:["tenuous","exhaustive","compelling","unanimous"],
  e:[null,"*Exhaustive* means thorough and complete; one late dedication and silent letters are the opposite of thorough evidence.","*Compelling* means strong enough to convince; the colon lists reasons for doubt.","*Unanimous* means agreed by everyone; it describes people's views, not the strength of a piece of evidence."],
  why:"The letters say nothing of the niece, and the only link was added later by someone else, so the evidence is very weak: tenuous at best.",
  h:"Read the reasons after the colon: do they make the link stronger or weaker?" },
{ id:"sv-18", t:"wic", d:"sci", lv:"C1", f:"fix", w:"exacerbate",
  p:"Farmers in one dry region began pumping groundwater to irrigate their fields during a long drought. The pumping kept the crops alive for a few seasons, but by lowering the water table it ______ the drought's effects on nearby wetlands, which dried out more severely than in any earlier dry period.",
  o:["exacerbated","mitigated","belied","stymied"],
  e:[null,"*Mitigated* means made less severe; the wetlands dried out more severely than ever, so the effects grew worse.","*Belied* means gave a false picture of; the pumping changed the drought's effects, it did not disguise them.","*Stymied* means blocked; the drought's effects were strengthened, not stopped."],
  why:"Lowering the water table made the drought's damage to the wetlands worse than before: making a bad situation worse is exacerbating it.",
  h:"Were the wetlands better or worse off after the pumping began?" },
{ id:"sv-19", t:"transition", d:"hist", lv:"C1", f:"transition", w:"accordingly",
  p:"After a new bridge opened, most of the farmers who sold produce at one town's weekly market began arriving from the eastern bank of the river rather than the western. ______ the town council moved the market from the west bank to the east, closer to where its sellers now came from.",
  o:["Accordingly,","In contrast,","In other words,","For instance,"],
  e:[null,"*In contrast* signals that the second sentence pulls against the first; moving the market fits the change in where sellers came from.","*In other words* restates the previous sentence; moving the market is a new action, not a restatement.","*For instance* introduces an example; the council's decision is a response to the change, not an example of it."],
  why:"The council moved the market because sellers now came from the east, a response that suits the change: a fitting result is signalled by accordingly.",
  h:"Is the council's decision a contrast, an example, a restatement or a response?" },
{ id:"sv-20", t:"transition", d:"sci", lv:"C1", f:"transition", w:"that-said",
  p:"Laboratory tests show that a new coating keeps steel bridges free of rust for at least twenty years, twice as long as the paint now in use. ______ the coating costs nearly three times as much to apply, and it must be sprayed on in dry weather, which limits when crews can work.",
  o:["That said,","As a result,","In other words,","For example,"],
  e:[null,"*As a result* signals that the second sentence follows from the first; the coating's long life does not cause its high cost.","*In other words* restates the first sentence; the second sentence adds drawbacks, which is new information.","*For example* introduces an instance of the previous point; cost and weather limits are not examples of rust protection."],
  why:"The twenty-year protection still stands, and the second sentence limits it with costs and drawbacks: a concession, signalled by that said.",
  h:"Do the cost and the weather limits cancel the test results or only limit them?" }
],

final: [
{ id:"fi-01", t:"wic", d:"lit", lv:"C1", f:"attitude", w:"sanguine",
  p:"When the boat's engine failed a mile from shore, the younger passengers began to panic. Old Mrs Kanya alone remained ______, settling back against the rail and remarking that the tide would carry them home before supper, as it always had.",
  o:["sanguine","recalcitrant","ambivalent","despondent"],
  e:[null,"*Recalcitrant* means stubbornly refusing to obey; Mrs Kanya refuses nothing, she simply expects a safe return.","*Ambivalent* means pulled between opposite feelings; Mrs Kanya shows only calm confidence.","*Despondent* means without hope; she expects to be home before supper."],
  why:"While others panic, she calmly expects the tide to bring them home: quiet confidence in a good outcome when others are worried is being sanguine.",
  h:"What does Mrs Kanya expect to happen, and how does that differ from the others' reaction?" },
{ id:"fi-02", t:"wic", d:"hum", lv:"C1", f:"centre", w:"immaterial-to",
  p:"The rules of the poetry competition state that entries are judged without the poets' names attached, so a writer's age, school and previous prizes are ______ the judges' decision. Only the poem on the page is considered.",
  o:["immaterial to","integral to","detrimental to","a proxy for"],
  e:[null,"*Integral to* means essential to; the judges never see the writers' details, so these cannot be essential.","*Detrimental to* means harmful to; the details do no harm, they simply play no part.","*A proxy for* means a stand-in measure of; the judges measure only the poem itself."],
  why:"The judges see only the poem, so age, school and prizes make no difference to their decision: they are immaterial to it.",
  h:"What do the judges actually see when they score an entry?" },
{ id:"fi-03", t:"wic", d:"sci", lv:"C1", f:"fit", w:"incongruous-with",
  p:"Geologists studying a band of ancient seabed rock were puzzled by a thin layer of charcoal running through it. Charcoal forms when plants burn on land, so its presence seemed ______ everything else the rock revealed about a deep, still ocean floor.",
  o:["incongruous with","contingent on","indistinguishable from","conducive to"],
  e:[null,"*Contingent on* means depending on; the charcoal did not depend on the seabed, it seemed out of place there.","*Indistinguishable from* means impossible to tell apart from; charcoal from land fires is clearly different from seabed rock.","*Conducive to* means helping something happen; charcoal does not help create a deep ocean floor."],
  why:"Charcoal forms on land, so finding it in deep-sea rock seemed out of keeping with the rest of the evidence: incongruous with it.",
  h:"Where does charcoal normally form, and where was it found?" },
{ id:"fi-04", t:"wic", d:"hist", lv:"C1", f:"depend", w:"prevail-over",
  p:"For decades, two methods of preserving fish competed in the coastal villages: salting, which was cheap, and smoking, which gave a richer flavour. As roads improved, smoking gradually ______ salting, because buyers in distant towns were willing to pay more for the taste, and salted fish became rare.",
  o:["prevailed over","succumbed to","conformed to","coincided with"],
  e:[null,"*Succumbed to* means gave way to; salted fish became rare, so smoking was the winner.","*Conformed to* means followed a rule or standard; smoking replaced salting, it did not obey it.","*Coincided with* means happened at the same time as; the two methods competed and one won out."],
  why:"Smoking won the long competition and salted fish became rare: when one method proves stronger than another in the end, it prevails over it.",
  h:"Which method was still common at the end, and which became rare?" },
{ id:"fi-05", t:"wic", d:"sci", lv:"C1", f:"centre", w:"inconsequential-to",
  p:"The engineers worried that the faint vibration from a nearby railway would spoil the telescope's images. Careful measurements showed, however, that the vibration was ______ the telescope's performance: images taken while trains passed were as sharp as those taken at any other time.",
  o:["inconsequential to","detrimental to","integral to","responsive to"],
  e:[null,"*Detrimental to* means harmful to; the images were just as sharp when trains passed.","*Integral to* means an essential part of; the telescope works just as well with or without the vibration.","*Responsive to* means reacting to; the telescope's images did not change at all when the vibration came."],
  why:"Images were equally sharp with or without passing trains, so the vibration had no effect on performance: it was inconsequential to it.",
  h:"Were the images worse when the trains passed?" },
{ id:"fi-06", t:"wic", d:"hist", lv:"C2", f:"claim", w:"corroborate",
  p:"A merchant's diary claims that a severe frost destroyed the region's orange orchards in a certain year, but historians long doubted the account, since the merchant often exaggerated. Recently, scientists examining tree rings from the area found unusually narrow growth for that very year, evidence that appears to ______ the diary.",
  o:["corroborate","implement","contradict","embellish"],
  e:[null,"*Implement* means put a plan into action; tree rings can only support or oppose a diary's account.","*Contradict* means go against; narrow rings for that year fit a severe frost.","*Embellish* means add colourful details; that is what the merchant was suspected of, not what the tree-ring evidence does."],
  why:"Tree rings, a separate source, show poor growth in the very year the diary names, so they independently support the account: they corroborate it.",
  h:"Does the tree-ring evidence come from the merchant, and does it agree with the diary?" },
{ id:"fi-07", t:"wic", d:"hum", lv:"C1", f:"fit", w:"disparate",
  p:"The anthology brings together essays from ______ fields, among them marine biology, medieval music and city planning. Its editor makes no attempt to find a common theme, arguing instead that readers learn most when ideas from unrelated subjects meet.",
  o:["disparate","homogeneous","complementary","interchangeable"],
  e:[null,"*Homogeneous* means all of the same kind; the editor calls the subjects unrelated.","*Complementary* means completing each other as a set; the editor looks for no link between the fields at all.","*Interchangeable* means able to replace one another; marine biology and medieval music could hardly swap places."],
  why:"Marine biology, medieval music and city planning are unrelated subjects with no common theme: things very different in kind are disparate.",
  h:"How does the editor describe the subjects the essays come from?" },
{ id:"fi-08", t:"wic", d:"lit", lv:"C1", f:"visible", w:"belie",
  p:"Praew's voice on the telephone was bright and steady as she told her mother that her first week at university had gone well. Only her roommate, who had seen her crying over a failed quiz that morning, knew that the cheerful tone ______ a week of loneliness and worry.",
  o:["belied","betrayed","attested to","exacerbated"],
  e:[null,"*Betrayed* here would mean gave away without meaning to; her mother heard only cheerfulness, so the tone hid the truth.","*Attested to* means gave evidence of; a bright, steady voice gave no evidence of a lonely, worried week.","*Exacerbated* means made worse; the tone covered up her troubles, it did not add to them."],
  why:"Her bright tone gave her mother a false picture of a lonely, worried week: when an appearance hides the truth, it belies it.",
  h:"Did her mother learn about the hard week from the tone of her voice?" },
{ id:"fi-09", t:"wic", d:"hist", lv:"C2", f:"fix", w:"precipitate",
  p:"The medieval harbour wall of one fishing town had been weakening for centuries, its stones loosened by salt and frost. Yet it was a single winter storm that ______ its collapse: in one night, waves tore a gap thirty metres wide, and the wall was never rebuilt.",
  o:["precipitated","ameliorated","forestalled","substantiated"],
  e:[null,"*Ameliorated* means made a bad situation better; the storm tore a thirty-metre gap in one night.","*Forestalled* means prevented by acting first; the storm did not prevent the collapse, it brought it about.","*Substantiated* means supported a claim with evidence; a storm acts on a wall, not on a claim."],
  why:"Centuries of weathering weakened the wall, but the storm made the collapse happen suddenly: the final push that brings on an event precipitates it.",
  h:"What was the long-term cause, and what was the sudden final push?" },
{ id:"fi-10", t:"wic", d:"hum", lv:"C2", f:"fix", w:"stymie",
  p:"Efforts to translate a newly discovered manuscript have been ______ by its condition: water has blurred much of the ink, and several pages crumble at a touch, so scholars can study only a few lines at a time.",
  o:["stymied","compounded","buttressed","circumvented"],
  e:[null,"*Compounded* means made a difficulty worse; efforts are not a difficulty, and here the blurred ink blocks them.","*Buttressed* means supported and strengthened; blurred ink and crumbling pages hold the work back.","*Circumvented* means got round an obstacle; here the manuscript's condition is the obstacle, and nobody has got round it."],
  why:"Blurred ink and crumbling pages block the scholars, letting them study only a few lines at a time: the efforts have been stymied.",
  h:"Has the manuscript's condition helped the translators or held them back?" },
{ id:"fi-11", t:"wic", d:"sci", lv:"C2", f:"depend", w:"proxies-for",
  p:"Ice cores drilled from glaciers contain tiny bubbles of air trapped as snow fell and hardened over thousands of years. Climate scientists treat the chemistry of these bubbles as ______ the composition of the ancient atmosphere, since no direct measurements from that time exist.",
  o:["a proxy for","a catalyst of","a dearth of","a harbinger of"],
  e:[null,"*A catalyst of* is something that causes a change; the bubbles did not cause the ancient atmosphere.","*A dearth of* means a lack of; the bubbles hold ancient air to analyse, and they stand in for the atmosphere.","*A harbinger of* announces something still to come; the bubbles record the past, not a future event."],
  why:"The ancient air cannot be measured directly, so scientists measure the bubbles in its place: a measurable stand-in is a proxy for the unmeasurable thing.",
  h:"Can scientists measure the ancient atmosphere directly? What do they measure instead?" },
{ id:"fi-12", t:"wic", d:"hist", lv:"C2", f:"centre", w:"peripheral",
  p:"In most histories of the city's printing trade, the women who folded and stitched the pages are clearly named and pictured, but they are treated as ______ the story, which centres on the owners of the presses. A new study argues that their speed and skill set the pace of every workshop.",
  o:["peripheral to","concealed in","antithetical to","integral to"],
  e:[null,"*Concealed in* means hidden in; the women are clearly named and pictured, so the histories do not hide them.","*Antithetical to* means directly opposed to; the histories leave the women at the edge, they do not set them against the story.","*Integral to* means essential to; that is the new study's view, which the passage sets against most histories."],
  why:"The histories show the women but centre on the press owners, treating the women as minor: something kept at the edge of a subject is peripheral to it.",
  h:"The women are visible in the histories. How important are they made to seem?" },
{ id:"fi-13", t:"wic", d:"lit", lv:"C2", f:"visible", w:"latent",
  p:"For most of the novel, Aom's talent for drawing is ______, glimpsed only in the margins of her school notebooks. It is not until her aunt finds the notebooks and enrols her in an evening class that the gift begins to shape the course of her life.",
  o:["latent","operative","manifest","spurious"],
  e:[null,"*Operative* means working and having an effect; the gift shapes nothing until the evening class.","*Manifest* means plainly visible; the drawings are hidden in notebook margins until her aunt finds them.","*Spurious* means false or fake; the talent is real, since it later shapes her whole life."],
  why:"Aom's talent is real but hidden and inactive until the evening class brings it out: something present but not yet developed or showing is latent.",
  h:"Is the talent real? Is it active and visible for most of the novel?" },
{ id:"fi-14", t:"wic", d:"sci", lv:"C2", f:"fix", w:"mitigate",
  p:"Coastal engineers in one study planted dense belts of mangrove seedlings in front of a sea wall. The young trees could not stop storm waves from reaching the wall, but by slowing the water and absorbing some of its force they helped to ______ the damage each storm caused.",
  o:["mitigate","militate","exacerbate","precipitate"],
  e:[null,"*Militate* means work against and needs *against* after it; it cannot take *the damage* as a direct object.","*Exacerbate* means make worse; slowing the water and absorbing its force reduce the damage.","*Precipitate* means make something happen suddenly; the trees lessen the damage, they do not bring it on."],
  why:"The trees cannot stop the waves but reduce their force, making the damage less severe: lessening a harm without preventing it is mitigating it.",
  h:"Did the trees stop the damage, reduce it or increase it?" },
{ id:"fi-15", t:"wic", d:"hum", lv:"C2", f:"claim", w:"substantiate",
  p:"An art dealer has announced that a small unsigned portrait is the work of a celebrated painter, but the dealer has offered no documents, technical analysis or expert opinion in support. Until such evidence appears, the attribution remains ______, though it may yet prove correct.",
  o:["unsubstantiated","untenable","corroborated","anomalous"],
  e:[null,"*Untenable* means impossible to defend; the attribution may yet prove correct, so it has not been ruled out.","*Corroborated* means supported by separate evidence; no evidence of any kind has been offered.","*Anomalous* means not fitting a pattern; the passage is about missing evidence, and no pattern is described."],
  why:"No evidence supports the dealer's claim, but nothing has ruled it out either: a claim not yet backed by evidence is unsubstantiated.",
  h:"Has the claim been supported, disproved, or neither?" },
{ id:"fi-16", t:"meaning", mw:"plain", d:"lit", lv:"C1", f:"visible", w:null,
  p:"Nina said nothing when her sister announced that she would not be coming home for the holidays. Her silence, however, made her disappointment plain to everyone at the table, and her mother quietly changed the subject.",
  o:["evident","simple","ordinary","blunt"],
  e:[null,"*Simple* is the sense of plain in *plain food*; her silence did not make her feelings uncomplicated.","*Ordinary* is the sense in *plain clothes*; the point is that everyone could see the disappointment.","*Blunt* is the sense in *plain speaking*; Nina said nothing, so she was not direct in words."],
  why:"Everyone at the table could see Nina's disappointment, and her mother changed the subject, so plain here means clearly seen: evident.",
  h:"Could the others at the table see how Nina felt?" },
{ id:"fi-17", t:"meaning", mw:"qualified", d:"lit", lv:"C2", f:"claim", w:null,
  p:"The headmistress praised the girls' production of the play for its energy and its bold costumes. She qualified her praise, however, by adding that several actors had spoken too quickly to be understood from the back of the hall.",
  o:["limited","earned","certified","trained"],
  e:[null,"*Earned* reflects *qualified for a prize*; the headmistress was adding a criticism, not winning anything.","*Certified* reflects *a qualified nurse*; praise cannot be given an official qualification.","*Trained* also reflects having qualifications; her remark about fast speech made the praise less complete."],
  why:"By pointing out the fast speech, she kept her praise but made it less complete: to qualify a statement is to limit it.",
  h:"Did her extra remark add to the praise or hold some of it back?" },
{ id:"fi-18", t:"transition", d:"hist", lv:"C1", f:"transition", w:"accordingly",
  p:"Surveys in one coastal province found that most visitors to its small museums arrived by bicycle along the shore path rather than by car. ______ the museums' trust installed bicycle racks at every site and printed its new guide in a size that fits a cycling bag.",
  o:["Accordingly,","Similarly,","Nevertheless,","For instance,"],
  e:[null,"*Similarly* adds a parallel case; installing racks is a response to the survey, not a second, matching finding.","*Nevertheless* signals an action taken despite what came before; the racks and the guide suit the cyclists instead of going against the survey.","*For instance* introduces an example of the previous point; the trust's actions are not examples of how visitors travel."],
  why:"Because most visitors cycle, the trust made changes that suit cyclists: a response that fits and follows from the facts is signalled by accordingly.",
  h:"Do the racks and the guide go against the survey, match it, illustrate it or respond to it?" },
{ id:"fi-19", t:"transition", d:"sci", lv:"C1", f:"transition", w:null,
  p:"The researchers found that the hummingbirds in their study preferred some flowers over others. ______ the birds visited red, tube-shaped flowers almost four times as often as flowers of any other colour or shape.",
  o:["Specifically,","However,","Nevertheless,","Similarly,"],
  e:[null,"*However* signals a contrast; the figures support the preference instead of pulling against it.","*Nevertheless* signals a point that goes against what came before; nothing in the second sentence limits the first.","*Similarly* adds a parallel case; the second sentence describes the same preference in more exact terms."],
  why:"The second sentence names exactly which flowers the birds preferred and by how much: a more precise version of the previous statement is introduced by specifically.",
  h:"Is the second sentence a new point, or a more exact version of the first?" },
{ id:"fi-20", t:"transition", d:"hum", lv:"C2", f:"transition", w:"that-said",
  p:"The architect's riverside library has been praised for its daylight: tall windows on every floor mean that readers rarely need lamps before evening. ______ the same windows let in so much heat that the reading rooms become uncomfortable on summer afternoons, a problem the architect has acknowledged.",
  o:["That said,","Indeed,","Specifically,","In other words,"],
  e:[null,"*Indeed* strengthens the previous point; uncomfortable heat works against the praise instead of reinforcing it.","*Specifically* gives a more exact version of the previous point; the heat is a new problem, not a detail of the daylight.","*In other words* restates the previous point; the second sentence moves from a strength to a weakness."],
  why:"The praise for the daylight stands, and the second sentence adds a drawback from the same windows without cancelling it: a concession, signalled by that said.",
  h:"Does the second sentence strengthen the praise, restate it or limit it?" }
]
};
